syntax = "proto3";

package energy.v1;

// One sample from a field site. `at_ms` is an epoch-millisecond integer; it is
// deliberately not a google.protobuf.Timestamp so the wire value has no locale
// or timezone dependency.
message Reading {
  string site_id = 1;
  int64 watts = 2;
  int64 at_ms = 3;
}

message GetReadingRequest {
  string site_id = 1;
}

// `limit` is optional. When it is absent the service returns every reading.
// A present value must be a non-negative integer; 0 is a valid empty page.
message StreamReadingsRequest {
  string site_id = 1;
  optional int32 limit = 2;
}

service EnergyService {
  // Unary: the first (current) reading for a site.
  rpc GetReading(GetReadingRequest) returns (Reading);

  // Server stream: one Reading per message, in source order.
  rpc StreamReadings(StreamReadingsRequest) returns (stream Reading);
}

