"use strict";

/**
 * The gRPC framing and protobuf codec used by the service.
 *
 * A gRPC message is a 5-byte header followed by the protobuf bytes:
 *
 *   byte 0      compressed flag (0 = identity)
 *   bytes 1..4  message length, unsigned big-endian
 *
 * Only the handful of protobuf constructs needed by energy.proto are
 * implemented here. Keeping the codec explicit avoids a third-party runtime
 * and, more importantly, makes the wire representation stable and testable.
 */

const GRPC_HEADER_SIZE = 5;
const MAX_MESSAGE_BYTES = 16 * 1024 * 1024;

const WIRE_VARINT = 0;
const WIRE_FIXED64 = 1;
const WIRE_LENGTH_DELIMITED = 2;
const WIRE_FIXED32 = 5;

// ---------------------------------------------------------------------------
// Protobuf primitives
// ---------------------------------------------------------------------------

function asBuffer(value) {
  if (Buffer.isBuffer(value)) return value;
  if (value instanceof Uint8Array) return Buffer.from(value.buffer, value.byteOffset, value.byteLength);
  throw new TypeError("expected a Buffer or Uint8Array");
}

function toBigInt(value, fieldName) {
  if (typeof value === "bigint") return value;
  if (typeof value === "number" && Number.isSafeInteger(value)) return BigInt(value);
  if (typeof value === "string" && /^-?\d+$/u.test(value)) return BigInt(value);
  throw new TypeError(`${fieldName} must be a safe integer or bigint`);
}

/** Encode an unsigned (or sign-extended two's-complement) protobuf varint. */
function encodeVarint(value) {
  let remaining = toBigInt(value, "varint");
  if (remaining < 0n) remaining = BigInt.asUintN(64, remaining);
  const bytes = [];
  do {
    let byte = Number(remaining & 0x7fn);
    remaining >>= 7n;
    if (remaining !== 0n) byte |= 0x80;
    bytes.push(byte);
  } while (remaining !== 0n);
  return Buffer.from(bytes);
}

function decodeVarint(buffer, offset = 0) {
  const source = asBuffer(buffer);
  let value = 0n;
  let shift = 0n;
  let index = offset;
  while (index < source.length) {
    const byte = source[index];
    index += 1;
    value |= BigInt(byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) return { value, offset: index };
    shift += 7n;
    if (shift > 70n) throw new Error("varint_too_long");
  }
  throw new Error("truncated_varint");
}

function encodeTag(fieldNumber, wireType) {
  if (!Number.isInteger(fieldNumber) || fieldNumber < 1 || fieldNumber > 0x1fffffff) {
    throw new RangeError("invalid protobuf field number");
  }
  return encodeVarint((BigInt(fieldNumber) << 3n) | BigInt(wireType));
}

function encodeVarintField(fieldNumber, value) {
  return Buffer.concat([encodeTag(fieldNumber, WIRE_VARINT), encodeVarint(value)]);
}

function encodeBytesField(fieldNumber, value) {
  const bytes = asBuffer(value);
  return Buffer.concat([encodeTag(fieldNumber, WIRE_LENGTH_DELIMITED), encodeVarint(bytes.length), bytes]);
}

function encodeStringField(fieldNumber, value) {
  if (typeof value !== "string") throw new TypeError("string field must be a string");
  return encodeBytesField(fieldNumber, Buffer.from(value, "utf8"));
}

/**
 * Decode protobuf fields into a Map<fieldNumber, Array<{wireType,value}>>.
 * Values are Buffers for length-delimited fields, BigInts for varints and
 * Buffers for fixed-width fields. Unknown fields are retained so they can be
 * skipped safely.
 */
function decodeFields(buffer) {
  const source = asBuffer(buffer);
  const fields = new Map();
  let offset = 0;
  while (offset < source.length) {
    const tag = decodeVarint(source, offset);
    offset = tag.offset;
    const tagValue = Number(tag.value);
    if (tagValue === 0) throw new Error("invalid_field_number");
    const fieldNumber = Math.floor(tagValue / 8);
    const wireType = tagValue & 7;
    let value;
    if (wireType === WIRE_VARINT) {
      const decoded = decodeVarint(source, offset);
      value = decoded.value;
      offset = decoded.offset;
    } else if (wireType === WIRE_LENGTH_DELIMITED) {
      const decoded = decodeVarint(source, offset);
      offset = decoded.offset;
      const length = Number(decoded.value);
      if (!Number.isSafeInteger(length) || length < 0 || offset + length > source.length) {
        throw new Error("truncated_length_delimited_field");
      }
      value = source.subarray(offset, offset + length);
      offset += length;
    } else if (wireType === WIRE_FIXED64) {
      if (offset + 8 > source.length) throw new Error("truncated_fixed64_field");
      value = source.subarray(offset, offset + 8);
      offset += 8;
    } else if (wireType === WIRE_FIXED32) {
      if (offset + 4 > source.length) throw new Error("truncated_fixed32_field");
      value = source.subarray(offset, offset + 4);
      offset += 4;
    } else {
      throw new Error(`unsupported_wire_type_${String(wireType)}`);
    }
    const entries = fields.get(fieldNumber);
    if (entries === undefined) fields.set(fieldNumber, [{ wireType, value }]);
    else entries.push({ wireType, value });
  }
  return fields;
}

function lastEntry(fields, fieldNumber, wireType) {
  const entries = fields.get(fieldNumber);
  if (entries === undefined) return undefined;
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    if (entries[index].wireType === wireType) return entries[index];
  }
  return undefined;
}

function readString(fields, fieldNumber, fallback = "") {
  const entry = lastEntry(fields, fieldNumber, WIRE_LENGTH_DELIMITED);
  return entry === undefined ? fallback : entry.value.toString("utf8");
}

function readInt64(fields, fieldNumber, fallback = 0) {
  const entry = lastEntry(fields, fieldNumber, WIRE_VARINT);
  return entry === undefined ? fallback : Number(BigInt.asIntN(64, entry.value));
}

function readInt32(fields, fieldNumber, fallback = 0) {
  const entry = lastEntry(fields, fieldNumber, WIRE_VARINT);
  return entry === undefined ? fallback : Number(BigInt.asIntN(32, entry.value));
}

// ---------------------------------------------------------------------------
// energy.proto messages
// ---------------------------------------------------------------------------

function encodeReading(reading) {
  if (reading === null || typeof reading !== "object") throw new TypeError("reading must be an object");
  const parts = [];
  if (reading.siteId !== undefined && reading.siteId !== null) {
    parts.push(encodeStringField(1, String(reading.siteId)));
  }
  parts.push(encodeVarintField(2, reading.watts ?? 0));
  parts.push(encodeVarintField(3, reading.atMs ?? 0));
  return Buffer.concat(parts);
}

function decodeReading(buffer) {
  const fields = decodeFields(buffer);
  return {
    siteId: readString(fields, 1),
    watts: readInt64(fields, 2),
    atMs: readInt64(fields, 3),
  };
}

function encodeGetReadingRequest(siteId) {
  const id = typeof siteId === "string" ? siteId : siteId?.siteId;
  if (typeof id !== "string") throw new TypeError("siteId must be a string");
  return encodeStringField(1, id);
}

function decodeGetReadingRequest(buffer) {
  const fields = decodeFields(buffer);
  return { siteId: readString(fields, 1) };
}

function encodeStreamReadingsRequest(request) {
  const source = typeof request === "string" ? { siteId: request } : request;
  if (source === null || typeof source !== "object") throw new TypeError("request must be an object");
  if (typeof source.siteId !== "string") throw new TypeError("siteId must be a string");
  const parts = [encodeStringField(1, source.siteId)];
  if (source.limit !== undefined && source.limit !== null) {
    const limit = toBigInt(source.limit, "limit");
    // int32 negatives are sign-extended to 64 bits by protobuf.
    parts.push(encodeVarintField(2, BigInt.asUintN(64, BigInt.asIntN(32, limit))));
  }
  return Buffer.concat(parts);
}

function decodeStreamReadingsRequest(buffer) {
  const fields = decodeFields(buffer);
  const limitEntry = lastEntry(fields, 2, WIRE_VARINT);
  const request = { siteId: readString(fields, 1) };
  if (limitEntry !== undefined) request.limit = Number(BigInt.asIntN(32, limitEntry.value));
  return request;
}

// ---------------------------------------------------------------------------
// gRPC message framing
// ---------------------------------------------------------------------------

/**
 * Wrap one protobuf message in the gRPC 5-byte header. When compression is
 * requested the caller is responsible for supplying compressed bytes; the
 * service itself only emits identity frames.
 */
function encodeFrame(payload, compressed = false) {
  const message = asBuffer(payload);
  if (message.length > MAX_MESSAGE_BYTES) throw new RangeError("message_too_large");
  const frame = Buffer.allocUnsafe(GRPC_HEADER_SIZE + message.length);
  frame[0] = compressed ? 1 : 0;
  frame.writeUInt32BE(message.length, 1);
  message.copy(frame, GRPC_HEADER_SIZE);
  return frame;
}

/** Decode one complete frame starting at `offset`. */
function decodeFrame(frame, offset = 0) {
  const source = asBuffer(frame);
  if (offset < 0 || offset + GRPC_HEADER_SIZE > source.length) throw new Error("truncated_grpc_header");
  const compressed = source[offset] !== 0;
  const length = source.readUInt32BE(offset + 1);
  if (length > MAX_MESSAGE_BYTES) throw new Error("message_too_large");
  const start = offset + GRPC_HEADER_SIZE;
  const end = start + length;
  if (end > source.length) throw new Error("truncated_grpc_message");
  const message = source.subarray(start, end);
  return { compressed, message, payload: message, length, offset: end };
}

function decodeFrames(buffer) {
  const source = asBuffer(buffer);
  const frames = [];
  let offset = 0;
  while (offset < source.length) {
    const frame = decodeFrame(source, offset);
    frames.push(frame);
    offset = frame.offset;
  }
  return frames;
}

function encodeFrames(payloads, compressed = false) {
  return Buffer.concat(Array.from(payloads, (payload) => encodeFrame(payload, compressed)));
}

/**
 * Incremental parser for data chunks arriving over an HTTP/2 stream. gRPC
 * frames are not aligned to DATA frame boundaries, so callers must not assume
 * one Buffer per message.
 */
class FrameParser {
  constructor() {
    this._buffer = Buffer.alloc(0);
  }

  push(chunk) {
    if (!chunk || chunk.length === 0) return [];
    const incoming = asBuffer(chunk);
    this._buffer = this._buffer.length === 0 ? incoming : Buffer.concat([this._buffer, incoming]);
    const messages = [];
    while (this._buffer.length >= GRPC_HEADER_SIZE) {
      const length = this._buffer.readUInt32BE(1);
      if (length > MAX_MESSAGE_BYTES) throw new Error("message_too_large");
      const total = GRPC_HEADER_SIZE + length;
      if (this._buffer.length < total) break;
      const frame = decodeFrame(this._buffer, 0);
      messages.push(frame);
      this._buffer = this._buffer.subarray(total);
    }
    return messages;
  }

  finish() {
    if (this._buffer.length !== 0) throw new Error("truncated_grpc_message");
    return [];
  }

  reset() {
    this._buffer = Buffer.alloc(0);
  }
}

module.exports = {
  GRPC_HEADER_SIZE,
  MAX_MESSAGE_BYTES,
  WIRE_VARINT,
  WIRE_LENGTH_DELIMITED,
  encodeVarint,
  decodeVarint,
  encodeTag,
  encodeVarintField,
  encodeBytesField,
  encodeStringField,
  decodeFields,
  encodeReading,
  decodeReading,
  encodeGetReadingRequest,
  decodeGetReadingRequest,
  encodeStreamReadingsRequest,
  decodeStreamReadingsRequest,
  encodeFrame,
  decodeFrame,
  decodeFrames,
  encodeFrames,
  FrameParser,
  // Common spellings used by gRPC examples/tests.
  encodeGrpcMessage: encodeFrame,
  decodeGrpcMessage: decodeFrame,
  encodeMessage: encodeFrame,
  decodeMessage: decodeFrame,
};

