"use strict";

/**
 * gRPC service for energy.v1.EnergyService, built directly on node:http2.
 *
 *   POST /energy.v1.EnergyService/GetReading
 *   POST /energy.v1.EnergyService/StreamReadings   (server streaming)
 *
 * Responses always carry a grpc-status trailer. Error statuses use the
 * canonical gRPC codes, and grpc-message carries the same stable codes the
 * REST baseline used (`unknown_site`, `invalid_limit`).
 */
const { createServer } = require("node:http2");

const { readingFor, readingsFor } = require("./data.js");
const wire = require("./wire.js");

const STATUS_OK = 0;
const STATUS_INVALID_ARGUMENT = 3;
const STATUS_NOT_FOUND = 5;
const STATUS_UNIMPLEMENTED = 12;
const STATUS_INTERNAL = 13;

const PATHS = Object.freeze({
  getReading: "/energy.v1.EnergyService/GetReading",
  streamReadings: "/energy.v1.EnergyService/StreamReadings",
});

class GrpcRequestError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function grpcMessageValue(message) {
  let encoded = "";
  for (const byte of Buffer.from(message, "utf8")) {
    if (byte >= 0x20 && byte <= 0x7e && byte !== 0x25) {
      encoded += String.fromCharCode(byte);
    } else {
      encoded += `%${byte.toString(16).toUpperCase().padStart(2, "0")}`;
    }
  }
  return encoded;
}

function responseHeaders() {
  return {
    ":status": 200,
    "content-type": "application/grpc",
    "grpc-accept-encoding": "identity",
    "cache-control": "no-cache",
  };
}

function beginResponse(stream) {
  stream.respond(responseHeaders(), { waitForTrailers: true });
}

function endWithStatus(stream, status, message) {
  if (stream.destroyed || stream.closed) return;
  const trailers = { "grpc-status": String(status) };
  if (message !== undefined) trailers["grpc-message"] = grpcMessageValue(message);
  stream.once("wantTrailers", () => {
    if (stream.destroyed || stream.closed) return;
    try {
      stream.sendTrailers(trailers);
    } catch {
      // The peer may have reset the stream while the handler was finishing.
    }
  });
  stream.end();
}

function readRequestBody(stream) {
  return new Promise((resolve, reject) => {
    const parser = new wire.FrameParser();
    const messages = [];
    stream.on("data", (chunk) => {
      try {
        messages.push(...parser.push(chunk));
      } catch (error) {
        reject(error);
      }
    });
    stream.on("end", () => {
      try {
        parser.finish();
        resolve(messages);
      } catch (error) {
        reject(error);
      }
    });
    stream.on("error", reject);
    stream.on("aborted", () => reject(new Error("request_aborted")));
  });
}

function oneRequestMessage(messages, stream) {
  if (messages.length === 0) throw new GrpcRequestError(STATUS_INVALID_ARGUMENT, "missing_request_message");
  if (messages.length !== 1) {
    throw new GrpcRequestError(STATUS_INVALID_ARGUMENT, "too_many_request_messages");
  }
  const message = messages[0];
  if (message.compressed) {
    endWithStatus(stream, STATUS_UNIMPLEMENTED, "compression_not_supported");
    return null;
  }
  return message.message;
}

function validLimit(request) {
  if (request.limit === undefined) return { ok: true, limit: undefined };
  if (!Number.isInteger(request.limit) || request.limit < 0) return { ok: false };
  return { ok: true, limit: request.limit };
}

function createGrpcServer(options) {
  const server = createServer(options);

  server.on("session", (session) => {
    // A client can disappear at any time; an unhandled session error would
    // otherwise take down the whole service.
    session.on("error", () => {});
  });

  server.on("stream", (stream, headers) => {
    stream.on("error", () => {});
    stream.on("close", () => {});

    const contentType = String(headers["content-type"] ?? "");
    const method = String(headers[":method"] ?? "");
    const rawPath = String(headers[":path"] ?? "");
    const path = rawPath.split("?", 1)[0];

    if (method !== "POST" || !contentType.toLowerCase().startsWith("application/grpc")) {
      beginResponse(stream);
      endWithStatus(stream, STATUS_UNIMPLEMENTED, "invalid_grpc_request");
      return;
    }

    if (path !== PATHS.getReading && path !== PATHS.streamReadings) {
      beginResponse(stream);
      endWithStatus(stream, STATUS_UNIMPLEMENTED, "unimplemented_method");
      return;
    }

    const handler = path === PATHS.getReading ? handleGetReading : handleStreamReadings;
    readRequestBody(stream)
      .then(async (messages) => {
        const payload = oneRequestMessage(messages, stream);
        if (payload === null) return;
        await handler(stream, payload);
      })
      .catch((error) => {
        if (stream.destroyed || stream.closed) return;
        if (!stream.headersSent) beginResponse(stream);
        const status = error instanceof GrpcRequestError ? error.status : STATUS_INTERNAL;
        endWithStatus(stream, status, error instanceof Error ? error.message : "internal_error");
      });
  });

  return server;
}

async function handleGetReading(stream, payload) {
  let request;
  try {
    request = wire.decodeGetReadingRequest(payload);
  } catch {
    beginResponse(stream);
    endWithStatus(stream, STATUS_INVALID_ARGUMENT, "malformed_request");
    return;
  }

  const reading = readingFor(request.siteId);
  beginResponse(stream);
  if (reading === null) {
    endWithStatus(stream, STATUS_NOT_FOUND, "unknown_site");
    return;
  }

  stream.write(wire.encodeFrame(wire.encodeReading(reading)));
  endWithStatus(stream, STATUS_OK);
}

async function handleStreamReadings(stream, payload) {
  let request;
  try {
    request = wire.decodeStreamReadingsRequest(payload);
  } catch {
    beginResponse(stream);
    endWithStatus(stream, STATUS_INVALID_ARGUMENT, "malformed_request");
    return;
  }

  beginResponse(stream);
  const readings = readingsFor(request.siteId);
  if (readings === null) {
    endWithStatus(stream, STATUS_NOT_FOUND, "unknown_site");
    return;
  }

  const limit = validLimit(request);
  if (!limit.ok) {
    endWithStatus(stream, STATUS_INVALID_ARGUMENT, "invalid_limit");
    return;
  }

  const selected = limit.limit === undefined ? readings : readings.slice(0, limit.limit);
  for (const reading of selected) {
    if (stream.destroyed || stream.closed) return;
    // One write and one gRPC frame per Reading keeps the mobile client's
    // incremental renderer and its small per-message budget happy.
    stream.write(wire.encodeFrame(wire.encodeReading(reading)));
    await new Promise((resolve) => setImmediate(resolve));
  }
  endWithStatus(stream, STATUS_OK);
}

function startGrpcServer({ port = 0, host = "127.0.0.1", options } = {}) {
  const server = createGrpcServer(options);
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, host, () => {
      server.removeListener("error", reject);
      resolve({ server, port: server.address().port });
    });
  });
}

module.exports = {
  PATHS,
  STATUS_OK,
  STATUS_INVALID_ARGUMENT,
  STATUS_NOT_FOUND,
  STATUS_UNIMPLEMENTED,
  STATUS_INTERNAL,
  createGrpcServer,
  startGrpcServer,
};

