"use strict";

/**
 * gRPC client for the fleet console.
 *
 * The public methods mirror the REST client: `getReading()` resolves to a
 * plain `{ siteId, watts, atMs }` object and `getReadings()` resolves to an
 * array in source order. `streamReadings()` additionally exposes each Reading
 * as soon as its gRPC frame arrives (callback and/or async iteration), which
 * is what the fleet mobile client needs for incremental rendering.
 */
const { connect } = require("node:http2");

const wire = require("./wire.js");

const PATHS = Object.freeze({
  getReading: "/energy.v1.EnergyService/GetReading",
  streamReadings: "/energy.v1.EnergyService/StreamReadings",
});

const STATUS_NAMES = Object.freeze({
  0: "OK",
  1: "CANCELLED",
  2: "UNKNOWN",
  3: "INVALID_ARGUMENT",
  4: "DEADLINE_EXCEEDED",
  5: "NOT_FOUND",
  6: "ALREADY_EXISTS",
  7: "PERMISSION_DENIED",
  8: "RESOURCE_EXHAUSTED",
  9: "FAILED_PRECONDITION",
  10: "ABORTED",
  11: "OUT_OF_RANGE",
  12: "UNIMPLEMENTED",
  13: "INTERNAL",
  14: "UNAVAILABLE",
  15: "DATA_LOSS",
  16: "UNAUTHENTICATED",
});

function decodeGrpcMessage(value) {
  if (value === undefined) return "";
  try {
    return decodeURIComponent(String(value));
  } catch {
    return String(value);
  }
}

function grpcError(status, message) {
  const code = STATUS_NAMES[status] ?? `GRPC_${String(status)}`;
  const error = new Error(message === "" ? code : message);
  error.code = code;
  error.grpcStatus = status;
  error.status = status;
  return error;
}

function statusOf(headers, trailers) {
  const value = trailers["grpc-status"] ?? headers["grpc-status"];
  return value === undefined ? 0 : Number(value);
}

function messageOf(headers, trailers) {
  return decodeGrpcMessage(trailers["grpc-message"] ?? headers["grpc-message"]);
}

function requestHeaders(path) {
  return {
    ":method": "POST",
    ":path": path,
    "content-type": "application/grpc",
    te: "trailers",
    "grpc-accept-encoding": "identity",
  };
}

function createGrpcClient(portOrOptions, extraOptions) {
  let options;
  if (portOrOptions !== null && typeof portOrOptions === "object") {
    options = { ...portOrOptions, ...(typeof extraOptions === "object" ? extraOptions : {}) };
  } else {
    options = { ...(typeof extraOptions === "object" ? extraOptions : {}), port: portOrOptions };
    if (typeof extraOptions === "string") options.host = extraOptions;
  }
  const port = options.port;
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new TypeError("grpc client requires a valid port");
  }
  const host = options.host ?? "127.0.0.1";
  const authority = options.authority ?? `${host}:${String(port)}`;
  const baseUrl = `http://${authority}`;
  const sessions = new Set();
  const activeStreams = new Set();

  function openSession() {
    const session = connect(baseUrl);
    sessions.add(session);
    session.once("close", () => {
      sessions.delete(session);
    });
    session.on("error", () => {});
    return session;
  }

  function closeSession(session) {
    sessions.delete(session);
    try {
      session.close();
    } catch {
      session.destroy();
    }
  }

  async function unaryCall(path, payload) {
    return await new Promise((resolve, reject) => {
      let session;
      try {
        session = openSession();
      } catch (error) {
        reject(error);
        return;
      }

      let settled = false;
      let responseHeaders = {};
      let trailers = {};
      const parser = new wire.FrameParser();
      const messages = [];

      const finish = (error, result) => {
        if (settled) return;
        settled = true;
        closeSession(session);
        if (error === null) resolve(result);
        else reject(error);
      };

      const stream = session.request(requestHeaders(path));
      stream.on("response", (headers) => {
        responseHeaders = headers;
      });
      stream.on("trailers", (received) => {
        trailers = { ...trailers, ...received };
      });
      stream.on("data", (chunk) => {
        try {
          messages.push(...parser.push(chunk));
        } catch (error) {
          stream.close();
          finish(error);
        }
      });
      stream.on("end", () => {
        try {
          parser.finish();
        } catch (error) {
          finish(error);
          return;
        }
        if (Number(responseHeaders[":status"] ?? 200) !== 200) {
          finish(new Error(`http_${String(responseHeaders[":status"])}`));
          return;
        }
        const status = statusOf(responseHeaders, trailers);
        if (status !== 0) {
          finish(grpcError(status, messageOf(responseHeaders, trailers)));
          return;
        }
        for (const message of messages) {
          if (message.compressed) {
            finish(new Error("compression_not_supported"));
            return;
          }
        }
        finish(null, messages.map((message) => message.message));
      });
      stream.on("error", (error) => finish(error));
      stream.on("close", () => {
        // A reset stream may not emit "end"; fail rather than hanging.
        if (!settled) {
          const status = statusOf(responseHeaders, trailers);
          finish(status === 0 ? grpcError(13, "stream_closed") : grpcError(status, messageOf(responseHeaders, trailers)));
        }
      });
      session.on("error", (error) => finish(error));

      stream.end(wire.encodeFrame(payload));
    });
  }

  function decodeReadingResponse(payload) {
    // The committed service contract returns Reading directly. Accepting the
    // conventional envelope as well costs nothing and keeps simple clients
    // interoperable during a rolling migration.
    const fields = wire.decodeFields(payload);
    if (!fields.has(2) && !fields.has(3)) {
      const entry = fields.get(1);
      if (entry !== undefined && entry.length > 0) {
        const nested = entry[entry.length - 1];
        const looksLikeReading = nested.wireType === 2 && nested.value.length > 0 && nested.value[0] === 0x0a;
        if (looksLikeReading && fields.size === 1) return wire.decodeReading(nested.value);
      }
    }
    return wire.decodeReading(payload);
  }

  async function getReading(siteId) {
    const messages = await unaryCall(PATHS.getReading, wire.encodeGetReadingRequest(siteId));
    if (messages.length !== 1) throw new Error("invalid_grpc_response_count");
    return decodeReadingResponse(messages[0]);
  }

  class ReadingStream {
    constructor(onReading) {
      this.readings = [];
      this._queue = [];
      this._waiters = [];
      this._done = false;
      this._error = null;
      this._onReading = typeof onReading === "function" ? onReading : null;
      this.promise = new Promise((resolve, reject) => {
        this._resolve = resolve;
        this._reject = reject;
      });
      // The promise is still observable by callers; this simply prevents an
      // unhandled rejection when a caller only consumes the async iterator.
      this.promise.catch(() => {});
      this.cancel = () => {};
    }

    _push(reading) {
      if (this._done) return;
      this.readings.push(reading);
      if (this._onReading !== null) this._onReading(reading);
      if (this._waiters.length > 0) {
        const waiter = this._waiters.shift();
        waiter.resolve({ value: reading, done: false });
      } else {
        this._queue.push(reading);
      }
    }

    _finish(error) {
      if (this._done) return;
      this._done = true;
      this._error = error ?? null;
      while (this._waiters.length > 0) {
        const waiter = this._waiters.shift();
        if (this._error === null) waiter.resolve({ value: undefined, done: true });
        else waiter.reject(this._error);
      }
      if (this._error === null) this._resolve(this.readings);
      else this._reject(this._error);
    }

    _next() {
      if (this._queue.length > 0) {
        return Promise.resolve({ value: this._queue.shift(), done: false });
      }
      if (this._done) {
        return this._error === null
          ? Promise.resolve({ value: undefined, done: true })
          : Promise.reject(this._error);
      }
      return new Promise((resolve, reject) => {
        this._waiters.push({ resolve, reject });
      });
    }

    [Symbol.asyncIterator]() {
      return {
        next: () => this._next(),
        return: async () => {
          this.cancel();
          return { value: undefined, done: true };
        },
      };
    }

    then(onFulfilled, onRejected) {
      return this.promise.then(onFulfilled, onRejected);
    }

    catch(onRejected) {
      return this.promise.catch(onRejected);
    }

    finally(onFinally) {
      return this.promise.finally(onFinally);
    }
  }

  function streamReadings(siteId, limitOrOptions, maybeOnReading) {
    let limit;
    let onReading = maybeOnReading;
    if (limitOrOptions !== null && typeof limitOrOptions === "object") {
      limit = limitOrOptions.limit;
      if (typeof limitOrOptions.onReading === "function") onReading = limitOrOptions.onReading;
    } else if (limitOrOptions !== undefined) {
      limit = limitOrOptions;
    }

    const readingStream = new ReadingStream(onReading);
    if (limit !== undefined && !Number.isInteger(limit)) {
      readingStream._finish(new Error("invalid_limit"));
      return readingStream;
    }
    let session;
    try {
      session = openSession();
    } catch (error) {
      readingStream._finish(error);
      return readingStream;
    }

    let settled = false;
    let responseHeaders = {};
    let trailers = {};
    let stream;
    let cancel = () => {};
    const parser = new wire.FrameParser();

    const finish = (error) => {
      if (settled) return;
      settled = true;
      activeStreams.delete(cancel);
      closeSession(session);
      readingStream._finish(error ?? null);
    };

    try {
      stream = session.request(requestHeaders(PATHS.streamReadings));
    } catch (error) {
      finish(error);
      return readingStream;
    }

    cancel = () => {
      if (settled) return;
      settled = true;
      activeStreams.delete(cancel);
      try {
        stream.close();
      } catch {
        // Already closed.
      }
      session.destroy();
      sessions.delete(session);
      readingStream._finish(null);
    };
    readingStream.cancel = cancel;
    activeStreams.add(cancel);

    stream.on("response", (headers) => {
      responseHeaders = headers;
    });
    stream.on("trailers", (received) => {
      trailers = { ...trailers, ...received };
    });
    stream.on("data", (chunk) => {
      try {
        for (const message of parser.push(chunk)) {
          if (message.compressed) throw new Error("compression_not_supported");
          readingStream._push(wire.decodeReading(message.message));
        }
      } catch (error) {
        try {
          stream.close();
        } catch {
          // Already closed.
        }
        finish(error);
      }
    });
    stream.on("end", () => {
      try {
        parser.finish();
      } catch (error) {
        finish(error);
        return;
      }
      const status = statusOf(responseHeaders, trailers);
      if (Number(responseHeaders[":status"] ?? 200) !== 200) {
        finish(new Error(`http_${String(responseHeaders[":status"])}`));
      } else if (status !== 0) {
        finish(grpcError(status, messageOf(responseHeaders, trailers)));
      } else {
        finish(null);
      }
    });
    stream.on("error", (error) => finish(error));
    stream.on("close", () => {
      if (!settled) {
        const status = statusOf(responseHeaders, trailers);
        finish(status === 0 ? null : grpcError(status, messageOf(responseHeaders, trailers)));
      }
    });
    session.on("error", (error) => finish(error));

    try {
      stream.end(wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId, limit })));
    } catch (error) {
      finish(error);
    }

    return readingStream;
  }

  return {
    getReading,
    async getReadings(siteId, limit) {
      return await streamReadings(siteId, limit);
    },
    streamReadings,
    close() {
      for (const cancel of [...activeStreams]) cancel();
      for (const session of [...sessions]) {
        try {
          session.close();
        } catch {
          session.destroy();
        }
      }
      sessions.clear();
    },
  };
}

module.exports = { createGrpcClient, PATHS };

