"use strict";

/**
 * Wire-level tests for the gRPC service. These deliberately use node:http2
 * directly instead of the project's client so the server's headers, message
 * framing and trailer statuses are independently exercised.
 */
const assert = require("node:assert/strict");
const http2 = require("node:http2");
const { after, before, test } = require("node:test");

const { SITES } = require("../service/data.js");
const { createGrpcServer, PATHS } = require("../service/grpc_server.js");
const wire = require("../service/wire.js");

let server;
let port;

before(async () => {
  server = createGrpcServer();
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  port = server.address().port;
});

after(async () => {
  await new Promise((resolve) => {
    server.close(resolve);
  });
});

function rawCall(path, payload) {
  return new Promise((resolve, reject) => {
    const session = http2.connect(`http://127.0.0.1:${String(port)}`);
    let settled = false;
    const finish = (error, result) => {
      if (settled) return;
      settled = true;
      session.close();
      if (error === null) resolve(result);
      else reject(error);
    };

    const stream = session.request({
      ":method": "POST",
      ":path": path,
      "content-type": "application/grpc",
      te: "trailers",
    });
    let headers = {};
    let trailers = {};
    const parser = new wire.FrameParser();
    const messages = [];

    stream.on("response", (received) => {
      headers = received;
    });
    stream.on("trailers", (received) => {
      trailers = { ...trailers, ...received };
    });
    stream.on("data", (chunk) => {
      try {
        messages.push(...parser.push(chunk));
      } catch (error) {
        stream.close();
        finish(error);
      }
    });
    stream.on("end", () => {
      try {
        parser.finish();
      } catch (error) {
        finish(error);
        return;
      }
      finish(null, { headers, trailers, messages });
    });
    stream.on("error", (error) => finish(error));
    session.on("error", (error) => finish(error));
    stream.end(wire.encodeFrame(payload));
  });
}

test("the gRPC frame is a 5-byte header plus the protobuf message", () => {
  const message = Buffer.from([0x0a, 0x03, 0x61, 0x62, 0x63]);
  const frame = wire.encodeFrame(message);
  assert.equal(frame.length, 5 + message.length);
  assert.equal(frame[0], 0);
  assert.equal(frame.readUInt32BE(1), message.length);
  assert.deepEqual(frame.subarray(5), message);

  const decoded = wire.decodeFrame(frame);
  assert.equal(decoded.compressed, false);
  assert.equal(decoded.length, message.length);
  assert.deepEqual(decoded.message, message);
});

test("the frame parser handles split and coalesced chunks", () => {
  const first = wire.encodeFrame(Buffer.from([1, 2, 3]));
  const second = wire.encodeFrame(Buffer.from([4, 5]));
  const parser = new wire.FrameParser();

  assert.deepEqual(parser.push(first.subarray(0, 2)), []);
  assert.deepEqual(
    parser.push(Buffer.concat([first.subarray(2), second])).map((frame) => [...frame.message]),
    [[1, 2, 3], [4, 5]],
  );
  assert.deepEqual(parser.finish(), []);
});

test("GetReading serves the current reading and a successful trailer", async () => {
  const response = await rawCall(PATHS.getReading, wire.encodeGetReadingRequest("site-a"));
  assert.equal(response.headers["content-type"], "application/grpc");
  assert.equal(response.trailers["grpc-status"], "0");
  assert.equal(response.messages.length, 1);
  assert.deepEqual(wire.decodeReading(response.messages[0].message), {
    siteId: "site-a",
    watts: 4120,
    atMs: 1762300000000,
  });
});

test("StreamReadings sends one under-16KiB frame per Reading in source order", async () => {
  const response = await rawCall(
    PATHS.streamReadings,
    wire.encodeStreamReadingsRequest({ siteId: "site-a" }),
  );
  assert.equal(response.trailers["grpc-status"], "0");
  assert.equal(response.messages.length, SITES["site-a"].length);
  for (const message of response.messages) {
    assert.ok(message.length < 16 * 1024, "each Reading frame must stay under 16 KiB");
  }
  assert.deepEqual(
    response.messages.map((message) => wire.decodeReading(message.message)),
    SITES["site-a"],
  );
});

test("limit bounds the stream and zero is an empty success", async () => {
  const limited = await rawCall(
    PATHS.streamReadings,
    wire.encodeStreamReadingsRequest({ siteId: "site-b", limit: 2 }),
  );
  assert.equal(limited.trailers["grpc-status"], "0");
  assert.equal(limited.messages.length, 2);

  const empty = await rawCall(
    PATHS.streamReadings,
    wire.encodeStreamReadingsRequest({ siteId: "site-b", limit: 0 }),
  );
  assert.equal(empty.trailers["grpc-status"], "0");
  assert.equal(empty.messages.length, 0);
});

test("an unknown site is NOT_FOUND, never an empty stream", async () => {
  for (const path of [PATHS.getReading, PATHS.streamReadings]) {
    const payload =
      path === PATHS.getReading
        ? wire.encodeGetReadingRequest("site-zz")
        : wire.encodeStreamReadingsRequest({ siteId: "site-zz" });
    const response = await rawCall(path, payload);
    assert.equal(response.trailers["grpc-status"], "5");
    assert.match(response.trailers["grpc-message"], /unknown_site/u);
    assert.equal(response.messages.length, 0);
  }
});

test("a negative limit is INVALID_ARGUMENT", async () => {
  const response = await rawCall(
    PATHS.streamReadings,
    wire.encodeStreamReadingsRequest({ siteId: "site-a", limit: -1 }),
  );
  assert.equal(response.trailers["grpc-status"], "3");
  assert.match(response.trailers["grpc-message"], /invalid_limit/u);
  assert.equal(response.messages.length, 0);
});

