"use strict";

/**
 * End-to-end migration tests: the same cases are driven through the REST
 * console client and the new gRPC fleet client, and a real HTTP/2 server is
 * started for the gRPC side.
 */
const assert = require("node:assert/strict");
const { after, before, test } = require("node:test");

const { SITES } = require("../service/data.js");
const { createGrpcClient } = require("../service/grpc_client.js");
const { createGrpcServer } = require("../service/grpc_server.js");
const { createRestClient } = require("../service/rest_client.js");
const { createRestServer } = require("../service/rest_server.js");

let restServer;
let grpcServer;
let rest;
let grpc;

before(async () => {
  restServer = createRestServer();
  await new Promise((resolve) => restServer.listen(0, "127.0.0.1", resolve));
  rest = createRestClient(restServer.address().port);

  grpcServer = createGrpcServer();
  await new Promise((resolve) => grpcServer.listen(0, "127.0.0.1", resolve));
  grpc = createGrpcClient(grpcServer.address().port);
});

after(async () => {
  grpc.close();
  await new Promise((resolve) => grpcServer.close(resolve));
  await new Promise((resolve) => restServer.close(resolve));
});

test("gRPC GetReading matches the REST console value", async () => {
  for (const siteId of Object.keys(SITES)) {
    assert.deepEqual(await grpc.getReading(siteId), await rest.getReading(siteId));
  }
});

test("gRPC StreamReadings matches REST batches and keeps source order", async () => {
  for (const siteId of Object.keys(SITES)) {
    for (const limit of [undefined, 0, 1, 2, 100]) {
      assert.deepEqual(
        await grpc.getReadings(siteId, limit),
        await rest.getReadings(siteId, limit),
        `${siteId} limit=${String(limit)}`,
      );
    }
  }
});

test("gRPC renders streamed readings as they arrive", async () => {
  const arrived = [];
  let completed = false;
  const stream = grpc.streamReadings("site-a", 3, (reading) => {
    assert.equal(completed, false, "a callback must run before the stream completes");
    arrived.push(reading);
  });
  const readings = await stream;
  completed = true;
  assert.equal(readings.length, 3);
  assert.deepEqual(arrived, readings);
  assert.deepEqual(
    readings.map((reading) => reading.atMs),
    [1762300000000, 1762300060000, 1762300120000],
  );
});

test("gRPC StreamReadings is consumable as an async iterable", async () => {
  const readings = [];
  for await (const reading of grpc.streamReadings("site-b", { limit: 2 })) {
    readings.push(reading);
  }
  assert.deepEqual(readings, (await rest.getReadings("site-b", 2)));
});

test("gRPC rejects unknown sites with the REST error code", async () => {
  await assert.rejects(() => grpc.getReading("site-zz"), /unknown_site/u);
  await assert.rejects(() => grpc.getReadings("site-zz"), /unknown_site/u);
  await assert.rejects(async () => {
    for await (const _reading of grpc.streamReadings("site-zz")) {
      // The stream must fail before yielding anything.
    }
  }, /unknown_site/u);
});

test("gRPC rejects an invalid limit with the REST error code", async () => {
  await assert.rejects(() => grpc.getReadings("site-a", -1), /invalid_limit/u);
  await assert.rejects(
    () => grpc.getReadings("site-a", 1.5),
    /invalid_limit|invalid_request_message_count/u,
  );
});
